def squash(s: str) -> str:
    out = []
    n = len(s)
    i = 0
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        run = j - i
        c = s[i]
        esc = "\\" + c if c == "\\" or "0" <= c <= "9" else c
        if run >= 3:
            out.append(str(run))
            out.append(esc)
        else:
            out.append(esc * run)
        i = j
    return "".join(out)
